contributions.installSql:
COMMENT ON TABLE "utils"."cache_entry" IS 'Disposable unlogged cache entries with expiration and tag-based invalidation.';
COMMENT ON COLUMN "utils"."cache_entry"."key" IS 'Unique application-defined cache key.';
COMMENT ON COLUMN "utils"."cache_entry"."value" IS 'JSON value stored for the cache key.';
COMMENT ON COLUMN "utils"."cache_entry"."tags" IS 'Application-defined tags used to invalidate related entries together.';
COMMENT ON COLUMN "utils"."cache_entry"."expires_at" IS 'Date and time after which the entry must be treated as expired.';
COMMENT ON COLUMN "utils"."cache_entry"."created_at" IS 'Date and time when the cache entry was created.';
COMMENT ON COLUMN "utils"."cache_entry"."size_bytes" IS 'Estimated serialized size used to enforce cache storage budgets.';

